const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');

Given('the app is loaded', function () {
  // App is loaded by Before hook in world.js
});

Given('a todo {string} exists', function (title) {
  const stored = this.window.localStorage.getItem('todos-vanilla');
  const todos = stored ? JSON.parse(stored) : [];
  todos.push({ id: todos.length + 1, title: title, completed: false });
  this.window.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  // Reload from localStorage and re-render
  this.window.eval('load(); render()');
});

Given('a completed todo {string} exists', function (title) {
  const stored = this.window.localStorage.getItem('todos-vanilla');
  const todos = stored ? JSON.parse(stored) : [];
  todos.push({ id: todos.length + 1, title: title, completed: true });
  this.window.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.window.eval('load(); render()');
});

Given('the following todos exist:', function (dataTable) {
  const rows = dataTable.hashes();
  const todos = [];
  let id = 1;
  rows.forEach(row => {
    todos.push({ id: id++, title: row.title, completed: row.completed === 'true' });
  });
  this.window.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.window.eval('load(); render()');
});

When('the user types {string} in the new-todo input and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, bubbles: true }));
});

When('the user toggles the checkbox for todo {string}', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const checkbox = li.querySelector('.toggle');
      checkbox.checked = !checkbox.checked;
      checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
      break;
    }
  }
});

When('the user clicks the toggle-all checkbox', function () {
  const checkbox = this.document.getElementById('toggle-all');
  checkbox.checked = !checkbox.checked;
  checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user destroys the todo {string}', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const destroyBtn = li.querySelector('.destroy');
      destroyBtn.click();
      break;
    }
  }
});

When('the user double-clicks the label of todo {string}', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
      break;
    }
  }
});

When('the user types {string} in the edit input and presses Enter', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, bubbles: true }));
});

When('the user types {string} in the edit input and presses Enter on blur', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the user types {string} in the edit input and presses Escape', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 27, bubbles: true }));
});

When('the user clears the edit input and presses Enter', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, bubbles: true }));
});

When('the page is reloaded', function () {
  this.loadApp();
});

When('the user clicks the clear-completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  btn.click();
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

Then('a todo with title {string} exists in the list', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === title);
  expect(found).to.be.true;
});

Then('the new-todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  expect(input.value).to.equal('');
});

Then('the todo list is empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(0);
});

Then('the new-todo input has focus', function () {
  const input = this.document.querySelector('.new-todo');
  expect(this.document.activeElement).to.equal(input);
});

Then('the todo {string} has the completed class', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      expect(li.classList.contains('completed')).to.be.true;
      break;
    }
  }
});

Then('the todo {string} does not have the completed class', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      expect(li.classList.contains('completed')).to.be.false;
      break;
    }
  }
});

Then('all todos are completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  items.forEach(li => {
    expect(li.classList.contains('completed')).to.be.true;
  });
});

Then('the toggle-all checkbox is checked', function () {
  const checkbox = this.document.getElementById('toggle-all');
  expect(checkbox.checked).to.be.true;
});

Then('all todos are active', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  items.forEach(li => {
    expect(li.classList.contains('completed')).to.be.false;
  });
});

Then('the toggle-all checkbox is not checked', function () {
  const checkbox = this.document.getElementById('toggle-all');
  expect(checkbox.checked).to.be.false;
});

Then('the todo {string} no longer exists', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === title);
  expect(found).to.be.false;
});

Then('the todo {string} is in editing mode', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      expect(li.classList.contains('editing')).to.be.true;
      break;
    }
  }
});

Then('the edit input for {string} has focus', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const editInput = li.querySelector('.edit');
      expect(this.document.activeElement).to.equal(editInput);
      break;
    }
  }
});

Then('the todo {string} does not exist', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === title);
  expect(found).to.be.false;
});

Then('the todo {string} has the editing class', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      expect(li.classList.contains('editing')).to.be.true;
      break;
    }
  }
});

Then('the todo {string} does not have the editing class', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      expect(li.classList.contains('editing')).to.be.false;
      break;
    }
  }
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  expect(main.style.display).to.equal('none');
});

Then('the footer section is hidden', function () {
  const footer = this.document.querySelector('.footer');
  expect(footer.style.display).to.equal('none');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  expect(main.style.display).to.not.equal('none');
});

Then('the footer section is visible', function () {
  const footer = this.document.querySelector('.footer');
  expect(footer.style.display).to.not.equal('none');
});

Then('the counter displays {string}', function (text) {
  const count = this.document.querySelector('.todo-count');
  expect(count.textContent).to.equal(text);
});

Then('the clear-completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  expect(btn.style.display).to.equal('none');
});

Then('the clear-completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  expect(btn.style.display).to.not.equal('none');
});

Then('both todos are visible', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(2);
});

Then('only the todo {string} is visible', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(1);
  const label = items[0].querySelector('label');
  expect(label.textContent).to.equal(title);
});

Then('the filter link {string} is selected', function (name) {
  const links = this.document.querySelectorAll('.filters a');
  for (const link of links) {
    if (link.textContent === name) {
      expect(link.classList.contains('selected')).to.be.true;
    } else {
      expect(link.classList.contains('selected')).to.be.false;
    }
  }
});

Then('the todo {string} still exists', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === title);
  expect(found).to.be.true;
});

Then('the localStorage key {string} contains an array with {int} item', function (key, count) {
  const stored = this.window.localStorage.getItem(key);
  const arr = JSON.parse(stored);
  expect(arr.length).to.equal(count);
});

Then('the first item in localStorage {string} has title {string}', function (key, title) {
  const stored = this.window.localStorage.getItem(key);
  const arr = JSON.parse(stored);
  expect(arr[0].title).to.equal(title);
});

Then('the first item in localStorage {string} has id {int}', function (key, id) {
  const stored = this.window.localStorage.getItem(key);
  const arr = JSON.parse(stored);
  expect(arr[0].id).to.equal(id);
});

Then('the second item in localStorage {string} has id {int}', function (key, id) {
  const stored = this.window.localStorage.getItem(key);
  const arr = JSON.parse(stored);
  expect(arr[1].id).to.equal(id);
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Preserve localStorage across reloads
  _savedStorage = null;

  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // Save localStorage before creating new window
    if (this.window) {
      this._savedStorage = {};
      for (let i = 0; i < this.window.localStorage.length; i++) {
        const key = this.window.localStorage.key(i);
        this._savedStorage[key] = this.window.localStorage.getItem(key);
      }
    }

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // Restore saved localStorage
    if (this._savedStorage) {
      for (const [key, value] of Object.entries(this._savedStorage)) {
        this.window.localStorage.setItem(key, value);
      }
    }

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

(function () {
	'use strict';

	var STORAGE_KEY = 'todos-vanilla';
	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;

	var todos = [];
	var currentFilter = '/';
	var editingId = null;

	var todoList = document.querySelector('.todo-list');
	var newTodoInput = document.querySelector('.new-todo');
	var toggleAllCheckbox = document.getElementById('toggle-all');
	var mainSection = document.querySelector('.main');
	var footerSection = document.querySelector('.footer');
	var todoCount = document.querySelector('.todo-count');
	var clearCompletedBtn = document.querySelector('.clear-completed');
	var filterLinks = document.querySelectorAll('.filters a');

	function generateId() {
		var maxId = 0;
		todos.forEach(function (todo) {
			if (todo.id > maxId) maxId = todo.id;
		});
		return maxId + 1;
	}

	function save() {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	function load() {
		var stored = localStorage.getItem(STORAGE_KEY);
		if (stored) {
			try {
				todos = JSON.parse(stored);
			} catch (e) {
				todos = [];
			}
		}
	}
	window.load = load;

	function getFilteredTodos() {
		return todos.filter(function (todo) {
			if (currentFilter === '/active') return !todo.completed;
			if (currentFilter === '/completed') return todo.completed;
			return true;
		});
	}

	function render() {
		var filtered = getFilteredTodos();
		todoList.innerHTML = '';
		window.render = render;

		filtered.forEach(function (todo) {
			var li = document.createElement('li');
			li.setAttribute('data-id', todo.id);
			if (todo.completed) li.classList.add('completed');
			if (editingId === todo.id) li.classList.add('editing');

			var div = document.createElement('div');
			div.className = 'view';

			var checkbox = document.createElement('input');
			checkbox.className = 'toggle';
			checkbox.type = 'checkbox';
			checkbox.checked = todo.completed;
			checkbox.addEventListener('change', function () {
				toggleTodo(todo.id);
			});

			var label = document.createElement('label');
			label.textContent = todo.title;
			label.addEventListener('dblclick', function () {
				startEditing(todo.id);
			});

			var destroyBtn = document.createElement('button');
			destroyBtn.className = 'destroy';
			destroyBtn.addEventListener('click', function () {
				destroyTodo(todo.id);
			});

			div.appendChild(checkbox);
			div.appendChild(label);
			div.appendChild(destroyBtn);

			var editInput = document.createElement('input');
			editInput.className = 'edit';
			editInput.value = todo.title;
			editInput.addEventListener('blur', function () {
				finishEditing(todo.id, editInput.value);
			});
			editInput.addEventListener('keydown', function (e) {
				if (e.keyCode === ENTER_KEY) {
					finishEditing(todo.id, editInput.value);
				} else if (e.keyCode === ESCAPE_KEY) {
					cancelEditing();
				}
			});

			li.appendChild(div);
			li.appendChild(editInput);
			todoList.appendChild(li);

			if (editingId === todo.id) {
				editInput.focus();
			}
		});

		var activeCount = todos.filter(function (t) { return !t.completed; }).length;
		var completedCount = todos.filter(function (t) { return t.completed; }).length;

		todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

		mainSection.style.display = todos.length === 0 ? 'none' : '';
		footerSection.style.display = todos.length === 0 ? 'none' : '';

		clearCompletedBtn.style.display = completedCount === 0 ? 'none' : '';

		toggleAllCheckbox.checked = todos.length > 0 && activeCount === 0;

		filterLinks.forEach(function (link) {
			var href = link.getAttribute('href').replace('#', '');
			link.classList.toggle('selected', href === currentFilter);
		});

		save();
	}

	function addTodo(title) {
		var trimmed = title.trim();
		if (!trimmed) return;
		todos.push({
			id: generateId(),
			title: trimmed,
			completed: false
		});
		render();
	}

	function toggleTodo(id) {
		todos = todos.map(function (todo) {
			if (todo.id === id) {
				return { id: todo.id, title: todo.title, completed: !todo.completed };
			}
			return todo;
		});
		render();
	}

	function toggleAll() {
		var allCompleted = todos.every(function (t) { return t.completed; });
		todos = todos.map(function (todo) {
			return { id: todo.id, title: todo.title, completed: !allCompleted };
		});
		render();
	}

	function destroyTodo(id) {
		todos = todos.filter(function (todo) { return todo.id !== id; });
		render();
	}

	function startEditing(id) {
		editingId = id;
		render();
	}

	function finishEditing(id, newTitle) {
		var trimmed = newTitle.trim();
		if (!trimmed) {
			destroyTodo(id);
		} else {
			todos = todos.map(function (todo) {
				if (todo.id === id) {
					return { id: todo.id, title: trimmed, completed: todo.completed };
				}
				return todo;
			});
			editingId = null;
			render();
		}
	}

	function cancelEditing() {
		editingId = null;
		render();
	}

	function clearCompleted() {
		todos = todos.filter(function (todo) { return !todo.completed; });
		render();
	}

	function setFilter(filter) {
		currentFilter = filter;
		render();
	}

	// Event listeners
	newTodoInput.addEventListener('keydown', function (e) {
		if (e.keyCode === ENTER_KEY) {
			addTodo(newTodoInput.value);
			newTodoInput.value = '';
		}
	});

	toggleAllCheckbox.addEventListener('change', toggleAll);

	clearCompletedBtn.addEventListener('click', clearCompleted);

	filterLinks.forEach(function (link) {
		link.addEventListener('click', function (e) {
			e.preventDefault();
			setFilter(link.getAttribute('href').replace('#', ''));
		});
	});

	// Routing
	function handleHashChange() {
		var hash = window.location.hash || '#/';
		var filter = hash.replace('#', '');
		if (filter !== '/active' && filter !== '/completed') {
			filter = '/';
		}
		setFilter(filter);
	}

	window.addEventListener('hashchange', handleHashChange);

	// Initialize
	load();
	handleHashChange();
	render();
	newTodoInput.focus();
})();

