(function () {
	'use strict';

	var STORAGE_KEY = 'todos-vanilla';
	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;

	var todos = [];
	var currentFilter = '/';
	var editingId = null;

	var todoList = document.querySelector('.todo-list');
	var newTodoInput = document.querySelector('.new-todo');
	var toggleAllCheckbox = document.getElementById('toggle-all');
	var mainSection = document.querySelector('.main');
	var footerSection = document.querySelector('.footer');
	var todoCount = document.querySelector('.todo-count');
	var clearCompletedBtn = document.querySelector('.clear-completed');
	var filterLinks = document.querySelectorAll('.filters a');

	function generateId() {
		var maxId = 0;
		todos.forEach(function (todo) {
			if (todo.id > maxId) maxId = todo.id;
		});
		return maxId + 1;
	}

	function save() {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	function load() {
		var stored = localStorage.getItem(STORAGE_KEY);
		if (stored) {
			try {
				todos = JSON.parse(stored);
			} catch (e) {
				todos = [];
			}
		}
	}
	window.load = load;

	function getFilteredTodos() {
		return todos.filter(function (todo) {
			if (currentFilter === '/active') return !todo.completed;
			if (currentFilter === '/completed') return todo.completed;
			return true;
		});
	}

	function render() {
		var filtered = getFilteredTodos();
		todoList.innerHTML = '';
		window.render = render;

		filtered.forEach(function (todo) {
			var li = document.createElement('li');
			li.setAttribute('data-id', todo.id);
			if (todo.completed) li.classList.add('completed');
			if (editingId === todo.id) li.classList.add('editing');

			var div = document.createElement('div');
			div.className = 'view';

			var checkbox = document.createElement('input');
			checkbox.className = 'toggle';
			checkbox.type = 'checkbox';
			checkbox.checked = todo.completed;
			checkbox.addEventListener('change', function () {
				toggleTodo(todo.id);
			});

			var label = document.createElement('label');
			label.textContent = todo.title;
			label.addEventListener('dblclick', function () {
				startEditing(todo.id);
			});

			var destroyBtn = document.createElement('button');
			destroyBtn.className = 'destroy';
			destroyBtn.addEventListener('click', function () {
				destroyTodo(todo.id);
			});

			div.appendChild(checkbox);
			div.appendChild(label);
			div.appendChild(destroyBtn);

			var editInput = document.createElement('input');
			editInput.className = 'edit';
			editInput.value = todo.title;
			editInput.addEventListener('blur', function () {
				finishEditing(todo.id, editInput.value);
			});
			editInput.addEventListener('keydown', function (e) {
				if (e.keyCode === ENTER_KEY) {
					finishEditing(todo.id, editInput.value);
				} else if (e.keyCode === ESCAPE_KEY) {
					cancelEditing();
				}
			});

			li.appendChild(div);
			li.appendChild(editInput);
			todoList.appendChild(li);

			if (editingId === todo.id) {
				editInput.focus();
			}
		});

		var activeCount = todos.filter(function (t) { return !t.completed; }).length;
		var completedCount = todos.filter(function (t) { return t.completed; }).length;

		todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

		mainSection.style.display = todos.length === 0 ? 'none' : '';
		footerSection.style.display = todos.length === 0 ? 'none' : '';

		clearCompletedBtn.style.display = completedCount === 0 ? 'none' : '';

		toggleAllCheckbox.checked = todos.length > 0 && activeCount === 0;

		filterLinks.forEach(function (link) {
			var href = link.getAttribute('href').replace('#', '');
			link.classList.toggle('selected', href === currentFilter);
		});

		save();
	}

	function addTodo(title) {
		var trimmed = title.trim();
		if (!trimmed) return;
		todos.push({
			id: generateId(),
			title: trimmed,
			completed: false
		});
		render();
	}

	function toggleTodo(id) {
		todos = todos.map(function (todo) {
			if (todo.id === id) {
				return { id: todo.id, title: todo.title, completed: !todo.completed };
			}
			return todo;
		});
		render();
	}

	function toggleAll() {
		var allCompleted = todos.every(function (t) { return t.completed; });
		todos = todos.map(function (todo) {
			return { id: todo.id, title: todo.title, completed: !allCompleted };
		});
		render();
	}

	function destroyTodo(id) {
		todos = todos.filter(function (todo) { return todo.id !== id; });
		render();
	}

	function startEditing(id) {
		editingId = id;
		render();
	}

	function finishEditing(id, newTitle) {
		var trimmed = newTitle.trim();
		if (!trimmed) {
			destroyTodo(id);
		} else {
			todos = todos.map(function (todo) {
				if (todo.id === id) {
					return { id: todo.id, title: trimmed, completed: todo.completed };
				}
				return todo;
			});
			editingId = null;
			render();
		}
	}

	function cancelEditing() {
		editingId = null;
		render();
	}

	function clearCompleted() {
		todos = todos.filter(function (todo) { return !todo.completed; });
		render();
	}

	function setFilter(filter) {
		currentFilter = filter;
		render();
	}

	// Event listeners
	newTodoInput.addEventListener('keydown', function (e) {
		if (e.keyCode === ENTER_KEY) {
			addTodo(newTodoInput.value);
			newTodoInput.value = '';
		}
	});

	toggleAllCheckbox.addEventListener('change', toggleAll);

	clearCompletedBtn.addEventListener('click', clearCompleted);

	filterLinks.forEach(function (link) {
		link.addEventListener('click', function (e) {
			e.preventDefault();
			setFilter(link.getAttribute('href').replace('#', ''));
		});
	});

	// Routing
	function handleHashChange() {
		var hash = window.location.hash || '#/';
		var filter = hash.replace('#', '');
		if (filter !== '/active' && filter !== '/completed') {
			filter = '/';
		}
		setFilter(filter);
	}

	window.addEventListener('hashchange', handleHashChange);

	// Initialize
	load();
	handleHashChange();
	render();
	newTodoInput.focus();
})();

